1	import { Vital } from "./vital";
2	import { Profile } from "./profile";
3	import {Store} from './store';
4	import { DeepAssignObject } from "./utils";
5	
6	const moment = require("moment");
7	
8	export interface HealthDataType {
9	  name: string;
10	  class: any;
11	  unit: string;
12	  tm_measurement_name: string;
13	  tm_unit_name: string;
14	  accessType: "read" | "write" | "readAndWrite";
15	  aggregate?: AggregateBy;
16	}
17	
18	export type AggregateBy = "hour" | "day" | "sourceAndDay";
19	export type BackgroundUpdateFrequency = "immediate" | "hourly" | "daily" | "weekly";
20	export type SortOrder = "asc" | "desc";
21	
22	export interface QueryRequest {
23	  startDate: Date;
24	  endDate: Date;
25	  dataType: HealthDataType;
26	  aggregateBy?: AggregateBy;
27	  /**
28	   * Default "asc"
29	   */
30	  sortOrder?: SortOrder;
31	  /**
32	   * Default undefined, so whatever the platform limit is.
33	   */
34	  limit?: number;
35	}
36	
37	export interface HealthResponseItem {
38	  dataType: HealthDataType;
39	  start: Date;
40	  end: Date;
41	  date: Date;
42	  value: number;
43	  source?: string;
44	}
45	
46	export interface TMReading {
47	  date: Date;
48	  readings: Array<any>;
49	  patient_measurements_attributes: Array<TMPatientMeasurement>;
50	}
51	
52	export interface TMPatientMeasurement {
53	  patient_id: number;
54	  measurement_name: string;
55	  measurement_unit_name: string;
56	  numvalue: number;
57	  active: boolean;
58	  date: Date;
59	}
60	
61	export interface HealthDataApi {
62	  isAvailable(updateGooglePlayServicesIfNeeded? /* for Android, default true */: boolean): Promise<boolean>;
63	  isAuthorized(): Promise<boolean>;
64	  requestAuthorization(): Promise<boolean>;
65	  query(opts: QueryRequest): Promise<Array<HealthResponseItem>>;
66	}
67	
68	export class MyMobileHealthKit implements HealthDataApi{
69	
70	  types: Array<HealthDataType>;
71	
72	  private healthStore: HKHealthStore;
73	
74	  constructor() {
75	    if (HKHealthStore.isHealthDataAvailable()) {
76	      this.healthStore = HKHealthStore.new();
77	    }
78	
79	    this.types = [
80	    //Mentioned in Word Doc
81	    { name: "forcedVitalCapacity", class: HKQuantityTypeIdentifierForcedVitalCapacity,       unit: "l",             tm_measurement_name: "fvc", tm_unit_name: "liters", accessType: "readAndWrite"},
82	    { name: "heartRate",           class: HKQuantityTypeIdentifierRestingHeartRate,           unit: 'count/min',     tm_measurement_name: "hr",  tm_unit_name: "bpm",   accessType: "readAndWrite"},
83	    { name: "height",              class: HKQuantityTypeIdentifierHeight,                    unit: 'cm',            tm_measurement_name: "ht",  tm_unit_name: "cm",    accessType: "readAndWrite"},
84	    { name: "oxygenSaturation",    class: HKQuantityTypeIdentifierOxygenSaturation,          unit: '%',             tm_measurement_name: "so2", tm_unit_name: "%",     accessType: "readAndWrite"},
85	    //{ name: "peakExpiratoryFlowRate", class: HKQuantityTypeIdentifierPeakExpiratoryFlowRate, unit: 'l/min', tm_measurement_name: "", accessType: "readAndWrite"},
86	    //{ name: "respiratoryRate", class: HKQuantityTypeIdentifierRespiratoryRate, unit: 'count/min', tm_measurement_name: "", accessType: "readAndWrite"},
87	      { name: "steps",                class: HKQuantityTypeIdentifierStepCount,              unit: 'count',         tm_measurement_name: "daily_steps",    tm_unit_name: "",     accessType: "readAndWrite", aggregate: 'day'},
88	    { name: "bloodPressureSystolic",  class: HKQuantityTypeIdentifierBloodPressureSystolic,  unit: 'mmHg',          tm_measurement_name: "sbp",            tm_unit_name: "mmhg", accessType: "readAndWrite"},
89	    { name: "bloodPressureDiastolic", class: HKQuantityTypeIdentifierBloodPressureDiastolic, unit: 'mmHg',          tm_measurement_name: "dbp",            tm_unit_name: "mmhg", accessType: "readAndWrite"},
90	    { name: "distance",               class: HKQuantityTypeIdentifierDistanceWalkingRunning, unit: 'km',            tm_measurement_name: "daily_distance", tm_unit_name: "km",   accessType: "readAndWrite", aggregate: 'day'},
91	    { name: "weight",                 class: HKQuantityTypeIdentifierBodyMass,               unit: 'kg',            tm_measurement_name: "wt",       tm_unit_name: "kg",         accessType: "readAndWrite"},
92	    { name: "bodyMassIndex",          class: HKQuantityTypeIdentifierBodyMassIndex,          unit: 'count',            tm_measurement_name: "bmi",   tm_unit_name: "",           accessType: "readAndWrite"},
93	    { name: "bloodGlucose",           class: HKQuantityTypeIdentifierBloodGlucose,           unit: 'mmol<180.1558>/l', tm_measurement_name: "bgc",   tm_unit_name: "mmol/l",     accessType: "readAndWrite"},
94	    { name: "bodyTemperature",        class: HKQuantityTypeIdentifierBodyTemperature,        unit: 'degC',             tm_measurement_name: "temp",  tm_unit_name: "c",          accessType: "readAndWrite"},
95	    //{ name: "basalBodyTemperature", class: HKQuantityTypeIdentifierBasalBodyTemperature, unit: 'degC', tm_measurement_name: "", accessType: "readAndWrite"},
96	    //{ name: "peripheralPerfusionIndex", class: HKQuantityTypeIdentifierPeripheralPerfusionIndex, unit: 'percent', tm_measurement_name: "", accessType: "readAndWrite"},
97	  ];
98	  }
99	
100	  static parseData(results: Array<Array<HealthResponseItem>>, sleepResults: Array<any>) {
101	
102	    let tmReading: TMReading = {
103	      date: new Date(),
104	      readings: [],
105	      patient_measurements_attributes: []
106	    };
107	
108	    //Remove empty collections
109	    results = results.filter(item => { return item.length > 0} );    
110	
111	
112	    let parsedData: Array<TMReading> = [];
113	    for (let hkMeasurementCollection of results) {
114	      for (let hkMeasurement of hkMeasurementCollection) {
115	
116	      
117	        let patientMeasurement: TMPatientMeasurement = {
118	          patient_id: parseInt(Profile.currentProfile.getPatientId()),
119	          measurement_name: hkMeasurement.dataType.tm_measurement_name,
120	          measurement_unit_name: hkMeasurement.dataType.tm_unit_name,
121	          numvalue: hkMeasurement.value,
122	          active: true,
123	          date: new Date(hkMeasurement.date),
124	        }
125	
126	        if (hkMeasurement.dataType.unit == "%") {
127	          patientMeasurement.numvalue = patientMeasurement.numvalue * 100.0;
128	        }
129	        tmReading.patient_measurements_attributes.push(patientMeasurement);
130	      }
131	    }
132	
133	    for (let sleepRes of sleepResults) {
134	      let sleepDataObj = {
135	        date: sleepRes.date,
136	        patient_measurements_attributes: []
137	      };
138	      for (let sleepObj of sleepRes.measurements) {
139	        let dataObj = {
140	          patient_id:  parseInt(Profile.currentProfile.getPatientId()),
141	          measurement_name: sleepObj.dataType.tm_measurement_name,
142	          measurement_unit_name: sleepObj.dataType.tm_unit_name,
143	          numvalue: sleepObj.value,
144	          active: true,
145	          date: sleepObj.date
146	        };
147	        sleepDataObj.patient_measurements_attributes.push(dataObj);
148	      }
149	      tmReading.readings.push(sleepDataObj);
150	    }
151	
152	    return {reading: tmReading};
153	  }
154	
155	  isAvailable(): Promise<boolean> {
156	    return new Promise<boolean>((resolve, reject) => {
157	      resolve(this.healthStore !== undefined);
158	    });
159	  }
160	
161	  requestSleepDataAuthorization(): Promise<boolean> {
162	    return new Promise<boolean> ((resolve, reject) => {
163	      if (this.healthStore === undefined) {
164	        reject("Health not available");
165	        return;
166	      }
167	      let typesToRead = NSMutableSet.alloc<HKObjectType>().init();
168	      typesToRead.addObject(HKObjectType.categoryTypeForIdentifier(HKCategoryTypeIdentifierSleepAnalysis));
169	      let typesToShare = NSMutableSet.alloc<HKObjectType>().init();
170	      typesToShare.addObject(HKObjectType.categoryTypeForIdentifier(HKCategoryTypeIdentifierSleepAnalysis));
171	      let _typesToShare = NSMutableSet.alloc<HKSampleType>().init();
172	      _typesToShare.addObject(HKSampleType.categoryTypeForIdentifier(HKCategoryTypeIdentifierSleepAnalysis));
173	
174	      this.healthStore.requestAuthorizationToShareTypesReadTypesCompletion(
175	        _typesToShare,
176	        typesToRead,
177	        (success, error) => {
178	          if (success) {
179	            resolve(true);
180	          } else {
181	            reject('You do not have permissions for sleep data');
182	          }
183	        }
184	    );
185	
186	    });
187	  }
188	
189	  queryForSleepData(): Promise<Array<any>> {
190	    let promise = new Promise<Array<any>>((resolve, reject) =>{
191	    let sleepType = HKObjectType.categoryTypeForIdentifier(HKCategoryTypeIdentifierSleepAnalysis);
192	    let sortDescriptor = new NSSortDescriptor({key: HKSampleSortIdentifierStartDate, ascending:false});
193	    var startDate = Store.getLastHealthKitSyncDate();
194	    startDate = moment(startDate).subtract(3, "day").toDate();
195	    let endDate = new Date();
196	    let predicate = HKQuery.predicateForSamplesWithStartDateEndDateOptions(startDate, endDate, HKQueryOptions.None);
197	    let query = HKSampleQuery.alloc().initWithSampleTypePredicateLimitSortDescriptorsResultsHandler(sleepType, 
198	      predicate, 
199	      HKObjectQueryNoLimit, 
200	      [sortDescriptor], 
201	      (query: HKSampleQuery, result: NSArray<HKCategorySample>, error: NSError) => {
202	        if (result){
203	          console.log(result);
204	          console.log("===================== Sleep Data =======================");
205	
206	          let sleepPatternData = this.getFormattedSleepData(result);
207	  
208	          console.log("Sleep summary -----------");
209	          console.log(sleepPatternData);
210	          resolve(sleepPatternData);
211	        } else {
212	          reject(error);
213	        }
214	      }
215	    );
216	    this.healthStore.executeQuery(query);
217	    });
218	
219	    return promise;
220	  }
221	
222	  getFormattedSleepData(rawResult: NSArray<HKCategorySample>): Array<any> {
223	    let resultArray: Array<any> = [];
224	    var startDate = Store.getLastHealthKitSyncDate();
225	    startDate = moment(startDate).subtract(300, "day").toDate();
226	    let startOfDayKey = moment(startDate).startOf('day').toDate();
227	    let startOfDaytime = moment(startOfDayKey).add(12,'h').toDate();
228	    let endOfDayTime = moment(startOfDaytime).add(24, 'h').toDate();
229	    let duration = moment.duration(moment(new Date()).diff(startOfDayKey));
230	    let passes = Math.floor(duration.asDays()) ;
231	
232	    let sources = { }
233	    let dups = { }
234	
235	
236	    for (let i = 0; i < rawResult.count; i++) {
237	      let srcName = rawResult[i].sourceRevision.source.name 
238	      let key = `srcName: ${srcName} start: ${rawResult[i].startDate} end: ${rawResult[i].endDate} ${this.getSleepType(rawResult[i].value)}`
239	
240	      console.log( `${key} diff: ${rawResult[i].endDate.getTime() - rawResult[i].startDate.getTime()}` )
241	
242	      if( dups[key] == null ){
243	        dups[key] = true
244	        
245	        if( sources[srcName] == null ){
246	          sources[srcName] = []
247	        }
248	        sources[srcName].push( rawResult[i])
249	      }
250	    }
251	
252	    // use the src with the most data ???
253	    let result: Array<HKCategorySample> = []
254	    for( let srcKey in sources ){
255	      let src = sources[srcKey]
256	      if( src.length > result.length){
257	        result = src
258	      }
259	    }
260	
261	
262	
263	    do {
264	      let awakeTotal = 0;
265	      let inbedTotal = 0;
266	      let asleepTotal = 0;
267	
268	      let sleepResObject = {
269	        date: startOfDaytime,
270	        measurements: []
271	      };
272	      
273	      for (let i = 0; i < result.length; i++) {
274	
275	        if (moment(result[i].startDate).isBetween(startOfDaytime, endOfDayTime)) {
276	          let valueType = this.getSleepType(result[i].value);     
277	          let diff = result[i].endDate.getTime() - result[i].startDate.getTime();
278	
279	          if (valueType == "asleep" ) {
280	              asleepTotal += diff;         
281	          } else if (valueType == "inbed" ) {
282	            inbedTotal += diff;
283	          } else if (valueType == "awake") {
284	            awakeTotal += diff;
285	          } 
286	        }
287	      }
288	
289	      let restlessTotal = inbedTotal - asleepTotal
290	      if( restlessTotal < 0 ){
291	        restlessTotal = 0
292	      }
293	     
294	      asleepTotal =  asleepTotal/(1000.0 * 60.0) 
295	      restlessTotal =  restlessTotal/(1000.0 * 60.0) 
296	      awakeTotal =  awakeTotal/(1000.0 * 60.0) 
297	
298	      let totalSleep = asleepTotal + restlessTotal
299	
300	      if( totalSleep > 0 ) {
301	        console.log( startOfDaytime )
302	        console.log( endOfDayTime )
303	        console.log( asleepTotal )
304	        console.log( restlessTotal )
305	        console.log( awakeTotal )
306	        console.log( inbedTotal/(1000.0 * 60.0)  )
307	
308	        let totalSleepObj = {
309	          dataType:{
310	            name: "sleepPattern",
311	            class: "HKCategoryTypeIdentifierSleepAnalysis",
312	            unit: "min",
313	            tm_measurement_name: "sleep_pattern",
314	            tm_unit_name: "min",
315	            accessType: "readAndWrite"
316	          },
317	          source: null,
318	          date: startOfDaytime,
319	          start: startOfDaytime,
320	          end: endOfDayTime,
321	          value: totalSleep,
322	          sleep_pattern: totalSleep
323	        };
324	
325	        let awakeSleepObj = { 
326	          dataType:{
327	            name: "sleepPattern",
328	            class: "HKCategoryTypeIdentifierSleepAnalysis",
329	            unit: "min",
330	            tm_measurement_name: "sleep_pattern_awake",
331	            tm_unit_name: "min",
332	            accessType: "readAndWrite"
333	          },
334	          source: null,
335	          date: startOfDaytime,
336	          start: startOfDaytime,
337	          end: endOfDayTime, 
338	          value: awakeTotal,
339	          sleep_pattern_awake: awakeTotal       
340	        };
341	
342	        let restlessSleepObj = {
343	          dataType:{
344	            name: "sleepPattern",
345	            class: "HKCategoryTypeIdentifierSleepAnalysis",
346	            unit: "min",
347	            tm_measurement_name: "sleep_pattern_restless",
348	            tm_unit_name: "min",
349	            accessType: "readAndWrite"
350	          },
351	          source: null,
352	          date: startOfDaytime,
353	          start: startOfDaytime,
354	          end: endOfDayTime, 
355	          value: restlessTotal,
356	          sleep_pattern_restless: restlessTotal          
357	        };
358	
359	        let asleepSleepObj = {
360	          dataType:{
361	            name: "sleepPattern",
362	            class: "HKCategoryTypeIdentifierSleepAnalysis",
363	            unit: "min",
364	            tm_measurement_name: "sleep_pattern_asleep",
365	            tm_unit_name: "min",
366	            accessType: "readAndWrite"
367	          },
368	          source: null,
369	          date: startOfDaytime,
370	          start: startOfDaytime,
371	          end: endOfDayTime, 
372	          value: asleepTotal,
373	          sleep_pattern_asleep: asleepTotal         
374	        };  
375	
376	        sleepResObject.measurements.push(totalSleepObj);
377	        sleepResObject.measurements.push(asleepSleepObj);
378	        sleepResObject.measurements.push(awakeSleepObj);
379	        sleepResObject.measurements.push(restlessSleepObj);
380	        resultArray.push(sleepResObject);
381	      }
382	
383	      passes--;
384	      startOfDaytime = moment(startOfDaytime).add(24, 'hours').toDate();
385	      endOfDayTime = moment(endOfDayTime).add(24, 'hours').toDate();
386	    } while (passes > 0);
387	    return resultArray;
388	  }
389	
390	  getDateString(dateVal: Date):string {
391	    return dateVal.getFullYear()+"-"+dateVal.getMonth()+"-"+dateVal.getDate();
392	  }
393	
394	  private getSleepType(val: HKCategoryValueSleepAnalysis): string {
395	    let res = "";
396	    if (val == HKCategoryValueSleepAnalysis.InBed) {
397	      res = "inbed";
398	    } else if (val == HKCategoryValueSleepAnalysis.Awake) {
399	      res = "awake";
400	    } else if (val == HKCategoryValueSleepAnalysis.Asleep) {
401	      res = "asleep";
402	    }
403	    return res;
404	  }
405	
406	  requestAuthorization(): Promise<boolean> {
407	    return new Promise<boolean>((resolve, reject) => {
408	      if (this.healthStore === undefined) {
409	        reject("Health not available");
410	        return;
411	      }
412	      let readDataTypes = NSMutableSet.alloc<HKObjectType>().init();
413	      let writeDataTypes = NSMutableSet.alloc<HKObjectType>().init();
414	      let _writeDataTypes = NSMutableSet.alloc<HKSampleType>().init();
415	      this.types.filter(t => t.accessType === "write" || t.accessType === "readAndWrite")
416	      .forEach(t => writeDataTypes.addObject(HKSampleType.quantityTypeForIdentifier(t.class)));
417	
418	      this.types.filter(t => t.accessType === "read" || t.accessType === "readAndWrite")
419	      .forEach(t => readDataTypes.addObject(HKObjectType.quantityTypeForIdentifier(t.class)));
420	      this.types.filter(t => t.accessType === "write" || t.accessType === "readAndWrite")
421	      .forEach(t => writeDataTypes.addObject(HKObjectType.quantityTypeForIdentifier(t.class)));
422	
423	      this.healthStore.requestAuthorizationToShareTypesReadTypesCompletion( _writeDataTypes, readDataTypes, (success, error) => {
424	        if (success) {
425	          resolve(true);
426	        } else {
427	          reject('You do not have permissions for requested data type');
428	        }
429	      });
430	    });
431	  } 
432	
433	  isAuthorized(): Promise<boolean> {
434	    return new Promise<boolean>((resolve, reject) => {
435	      if (this.healthStore === undefined) {
436	        reject("Health not available");
437	        return;
438	      }
439	
440	      let authorized = true;
441	      this.types.forEach(t => {
442	        authorized = authorized &&
443	          this.healthStore.authorizationStatusForType(HKObjectType.quantityTypeForIdentifier(t.class)) === HKAuthorizationStatus.SharingAuthorized;
444	      });
445	      resolve(authorized);
446	    });
447	  }
448	
449	  async query(options: QueryRequest): Promise<any> {
450	    console.log("HealthKit: Querying all Data");
451	    // let promises: Array<Promise<any>> = [];
452	    let results = [];
453	    for (var item of this.types) {
454	      let endDate = options.endDate || new Date();
455	      let startDate = options.startDate || new Date();
456	
457	      let opts: QueryRequest = {
458	        startDate: startDate,
459	        endDate: endDate,
460	        dataType: item,
461	        aggregateBy: options.aggregateBy || item.aggregate || "hour", // optional, one of: "hour", "day", "sourceAndDay"
462	        sortOrder: options.sortOrder || "desc" // optional, default "asc"
463	      };
464	      
465	      let result;
466	      if (item.aggregate && item.aggregate == 'day') { 
467	        result = await this.queryForAggregateData(opts)
468	      } else {
469	        result = await this.queryForQuantityData(opts);
470	      }
471	
472	      results.push(result);
473	    }
474	    let sleepResult = await this.queryForSleepData();
475	    if (sleepResult) {
476	      // for (let i = 0; i < sleepResult.length; i++) {
477	      //   results.push(sleepResult[i]);
478	      // }
479	      //results.push(sleepResult);
480	    }
481	
482	    return Promise.resolve(MyMobileHealthKit.parseData(results, sleepResult));
483	  }
484	
485	  private queryForQuantityData(opts: QueryRequest) {
486	    let promise = new Promise((resolve, reject) => {
487	
488	      let quantityType = HKObjectType.quantityTypeForIdentifier(opts.dataType.class);
489	      let predicate = HKQuery.predicateForSamplesWithStartDateEndDateOptions(opts.startDate, opts.endDate, HKQueryOptions.StrictStartDate);
490	      let endDateSortDescriptor = NSSortDescriptor.alloc().initWithKeyAscending(HKSampleSortIdentifierEndDate, opts.sortOrder !== "desc");
491	      let sortBy = NSArray.arrayWithObject<NSSortDescriptor>(endDateSortDescriptor);
492	
493	      // note that passing an invalid 'unitString' will crash the app (can't catch that error either)
494	      let unit = HKUnit.unitFromString(opts.dataType.unit);
495	
496	      console.log("HK Query for " + opts.dataType.class + " in units "+unit);
