import { Vital } from "./vital";
import { Profile } from "./profile";
import {Store} from './store';
import { DeepAssignObject } from "./utils";

const moment = require("moment");

export interface HealthDataType {
  name: string;
  class: any;
  unit: string;
  tm_measurement_name: string;
  tm_unit_name: string;
  accessType: "read" | "write" | "readAndWrite";
  aggregate?: AggregateBy;
}

export type AggregateBy = "hour" | "day" | "sourceAndDay";
export type BackgroundUpdateFrequency = "immediate" | "hourly" | "daily" | "weekly";
export type SortOrder = "asc" | "desc";

export interface QueryRequest {
  startDate: Date;
  endDate: Date;
  dataType: HealthDataType;
  aggregateBy?: AggregateBy;
  /**
   * Default "asc"
   */
  sortOrder?: SortOrder;
  /**
   * Default undefined, so whatever the platform limit is.
   */
  limit?: number;
}

export interface HealthResponseItem {
  dataType: HealthDataType;
  start: Date;
  end: Date;
  date: Date;
  value: number;
  source?: string;
}

export interface TMReading {
  date: Date;
  readings: Array<any>;
  patient_measurements_attributes: Array<TMPatientMeasurement>;
}

export interface TMPatientMeasurement {
  patient_id: number;
  measurement_name: string;
  measurement_unit_name: string;
  numvalue: number;
  active: boolean;
  date: Date;
}

export interface HealthDataApi {
  isAvailable(updateGooglePlayServicesIfNeeded? /* for Android, default true */: boolean): Promise<boolean>;
  isAuthorized(): Promise<boolean>;
  requestAuthorization(): Promise<boolean>;
  query(opts: QueryRequest): Promise<Array<HealthResponseItem>>;
}

export class MyMobileHealthKit implements HealthDataApi{

  types: Array<HealthDataType>;

  private healthStore: HKHealthStore;

  constructor() {
    if (HKHealthStore.isHealthDataAvailable()) {
      this.healthStore = HKHealthStore.new();
    }

    this.types = [
    //Mentioned in Word Doc
    { name: "forcedVitalCapacity", class: HKQuantityTypeIdentifierForcedVitalCapacity,       unit: "l",             tm_measurement_name: "fvc", tm_unit_name: "liters", accessType: "readAndWrite"},
    { name: "heartRate",           class: HKQuantityTypeIdentifierRestingHeartRate,           unit: 'count/min',     tm_measurement_name: "hr",  tm_unit_name: "bpm",   accessType: "readAndWrite"},
    { name: "height",              class: HKQuantityTypeIdentifierHeight,                    unit: 'cm',            tm_measurement_name: "ht",  tm_unit_name: "cm",    accessType: "readAndWrite"},
    { name: "oxygenSaturation",    class: HKQuantityTypeIdentifierOxygenSaturation,          unit: '%',             tm_measurement_name: "so2", tm_unit_name: "%",     accessType: "readAndWrite"},
    //{ name: "peakExpiratoryFlowRate", class: HKQuantityTypeIdentifierPeakExpiratoryFlowRate, unit: 'l/min', tm_measurement_name: "", accessType: "readAndWrite"},
    //{ name: "respiratoryRate", class: HKQuantityTypeIdentifierRespiratoryRate, unit: 'count/min', tm_measurement_name: "", accessType: "readAndWrite"},
      { name: "steps",                class: HKQuantityTypeIdentifierStepCount,              unit: 'count',         tm_measurement_name: "daily_steps",    tm_unit_name: "",     accessType: "readAndWrite", aggregate: 'day'},
    { name: "bloodPressureSystolic",  class: HKQuantityTypeIdentifierBloodPressureSystolic,  unit: 'mmHg',          tm_measurement_name: "sbp",            tm_unit_name: "mmhg", accessType: "readAndWrite"},
    { name: "bloodPressureDiastolic", class: HKQuantityTypeIdentifierBloodPressureDiastolic, unit: 'mmHg',          tm_measurement_name: "dbp",            tm_unit_name: "mmhg", accessType: "readAndWrite"},
    { name: "distance",               class: HKQuantityTypeIdentifierDistanceWalkingRunning, unit: 'km',            tm_measurement_name: "daily_distance", tm_unit_name: "km",   accessType: "readAndWrite", aggregate: 'day'},
    { name: "weight",                 class: HKQuantityTypeIdentifierBodyMass,               unit: 'kg',            tm_measurement_name: "wt",       tm_unit_name: "kg",         accessType: "readAndWrite"},
    { name: "bodyMassIndex",          class: HKQuantityTypeIdentifierBodyMassIndex,          unit: 'count',            tm_measurement_name: "bmi",   tm_unit_name: "",           accessType: "readAndWrite"},
    { name: "bloodGlucose",           class: HKQuantityTypeIdentifierBloodGlucose,           unit: 'mmol<180.1558>/l', tm_measurement_name: "bgc",   tm_unit_name: "mmol/l",     accessType: "readAndWrite"},
    { name: "bodyTemperature",        class: HKQuantityTypeIdentifierBodyTemperature,        unit: 'degC',             tm_measurement_name: "temp",  tm_unit_name: "c",          accessType: "readAndWrite"},
    //{ name: "basalBodyTemperature", class: HKQuantityTypeIdentifierBasalBodyTemperature, unit: 'degC', tm_measurement_name: "", accessType: "readAndWrite"},
    //{ name: "peripheralPerfusionIndex", class: HKQuantityTypeIdentifierPeripheralPerfusionIndex, unit: 'percent', tm_measurement_name: "", accessType: "readAndWrite"},
  ];
  }

  static parseData(results: Array<Array<HealthResponseItem>>, sleepResults: Array<any>) {

    let tmReading: TMReading = {
      date: new Date(),
      readings: [],
      patient_measurements_attributes: []
    };

    //Remove empty collections
    results = results.filter(item => { return item.length > 0} );    


    let parsedData: Array<TMReading> = [];
    for (let hkMeasurementCollection of results) {
      for (let hkMeasurement of hkMeasurementCollection) {


        let patientMeasurement: TMPatientMeasurement = {
          patient_id: parseInt(Profile.currentProfile.getPatientId()),
          measurement_name: hkMeasurement.dataType.tm_measurement_name,
          measurement_unit_name: hkMeasurement.dataType.tm_unit_name,
          numvalue: hkMeasurement.value,
          active: true,
          date: new Date(hkMeasurement.date),
        }

        if (hkMeasurement.dataType.unit == "%") {
          patientMeasurement.numvalue = patientMeasurement.numvalue * 100.0;
        }
        tmReading.patient_measurements_attributes.push(patientMeasurement);
      }
    }

    for (let sleepRes of sleepResults) {
      let sleepDataObj = {
        date: sleepRes.date,
        patient_measurements_attributes: []
      };
      for (let sleepObj of sleepRes.measurements) {
        let dataObj = {
          patient_id:  parseInt(Profile.currentProfile.getPatientId()),
          measurement_name: sleepObj.dataType.tm_measurement_name,
          measurement_unit_name: sleepObj.dataType.tm_unit_name,
          numvalue: sleepObj.value,
          active: true,
          date: sleepObj.date
        };
        sleepDataObj.patient_measurements_attributes.push(dataObj);
      }
      tmReading.readings.push(sleepDataObj);
    }

    return {reading: tmReading};
  }

  isAvailable(): Promise<boolean> {
    return new Promise<boolean>((resolve, reject) => {
      resolve(this.healthStore !== undefined);
    });
  }

  requestSleepDataAuthorization(): Promise<boolean> {
    return new Promise<boolean> ((resolve, reject) => {
      if (this.healthStore === undefined) {
        reject("Health not available");
        return;
      }
      let typesToRead = NSMutableSet.alloc<HKObjectType>().init();
      typesToRead.addObject(HKObjectType.categoryTypeForIdentifier(HKCategoryTypeIdentifierSleepAnalysis));
      let typesToShare = NSMutableSet.alloc<HKObjectType>().init();
      typesToShare.addObject(HKObjectType.categoryTypeForIdentifier(HKCategoryTypeIdentifierSleepAnalysis));
      let _typesToShare = NSMutableSet.alloc<HKSampleType>().init();
      _typesToShare.addObject(HKSampleType.categoryTypeForIdentifier(HKCategoryTypeIdentifierSleepAnalysis));

      this.healthStore.requestAuthorizationToShareTypesReadTypesCompletion(
        _typesToShare,
        typesToRead,
        (success, error) => {
          if (success) {
            resolve(true);
          } else {
            reject('You do not have permissions for sleep data');
          }
        }
    );

    });
  }

  queryForSleepData(): Promise<Array<any>> {
    let promise = new Promise<Array<any>>((resolve, reject) =>{
    let sleepType = HKObjectType.categoryTypeForIdentifier(HKCategoryTypeIdentifierSleepAnalysis);
    let sortDescriptor = new NSSortDescriptor({key: HKSampleSortIdentifierStartDate, ascending:false});
    var startDate = Store.getLastHealthKitSyncDate();
    startDate = moment(startDate).subtract(3, "day").toDate();
    let endDate = new Date();
    let predicate = HKQuery.predicateForSamplesWithStartDateEndDateOptions(startDate, endDate, HKQueryOptions.None);
    let query = HKSampleQuery.alloc().initWithSampleTypePredicateLimitSortDescriptorsResultsHandler(sleepType, 
      predicate, 
      HKObjectQueryNoLimit, 
      [sortDescriptor], 
      (query: HKSampleQuery, result: NSArray<HKCategorySample>, error: NSError) => {
        if (result){
          console.log(result);
          console.log("===================== Sleep Data =======================");

          let sleepPatternData = this.getFormattedSleepData(result);

          console.log("Sleep summary -----------");
          console.log(sleepPatternData);
          resolve(sleepPatternData);
        } else {
          reject(error);
        }
      }
    );
    this.healthStore.executeQuery(query);
    });

    return promise;
  }

  getFormattedSleepData(rawResult: NSArray<HKCategorySample>): Array<any> {
    let resultArray: Array<any> = [];
    var startDate = Store.getLastHealthKitSyncDate();
    startDate = moment(startDate).subtract(300, "day").toDate();
    let startOfDayKey = moment(startDate).startOf('day').toDate();
    let startOfDaytime = moment(startOfDayKey).add(12,'h').toDate();
    let endOfDayTime = moment(startOfDaytime).add(24, 'h').toDate();
    let duration = moment.duration(moment(new Date()).diff(startOfDayKey));
    let passes = Math.floor(duration.asDays()) ;

    let sources = { }
    let dups = { }


    for (let i = 0; i < rawResult.count; i++) {
      let srcName = rawResult[i].sourceRevision.source.name 
      let key = `srcName: ${srcName} start: ${rawResult[i].startDate} end: ${rawResult[i].endDate} ${this.getSleepType(rawResult[i].value)}`

      console.log( `${key} diff: ${rawResult[i].endDate.getTime() - rawResult[i].startDate.getTime()}` )

      if( dups[key] == null ){
        dups[key] = true

        if( sources[srcName] == null ){
          sources[srcName] = []
        }
        sources[srcName].push( rawResult[i])
      }
    }

    // use the src with the most data ???
    let result: Array<HKCategorySample> = []
    for( let srcKey in sources ){
      let src = sources[srcKey]
      if( src.length > result.length){
        result = src
      }
    }



    do {
      let awakeTotal = 0;
      let inbedTotal = 0;
      let asleepTotal = 0;

      let sleepResObject = {
        date: startOfDaytime,
        measurements: []
      };

      for (let i = 0; i < result.length; i++) {

        if (moment(result[i].startDate).isBetween(startOfDaytime, endOfDayTime)) {
          let valueType = this.getSleepType(result[i].value);     
          let diff = result[i].endDate.getTime() - result[i].startDate.getTime();

          if (valueType == "asleep" ) {
              asleepTotal += diff;         
          } else if (valueType == "inbed" ) {
            inbedTotal += diff;
          } else if (valueType == "awake") {
            awakeTotal += diff;
          } 
        }
      }

      let restlessTotal = inbedTotal - asleepTotal
      if( restlessTotal < 0 ){
        restlessTotal = 0
      }

      asleepTotal =  asleepTotal/(1000.0 * 60.0) 
      restlessTotal =  restlessTotal/(1000.0 * 60.0) 
      awakeTotal =  awakeTotal/(1000.0 * 60.0) 

      let totalSleep = asleepTotal + restlessTotal

      if( totalSleep > 0 ) {
        console.log( startOfDaytime )
        console.log( endOfDayTime )
        console.log( asleepTotal )
        console.log( restlessTotal )
        console.log( awakeTotal )
        console.log( inbedTotal/(1000.0 * 60.0)  )

        let totalSleepObj = {
          dataType:{
            name: "sleepPattern",
            class: "HKCategoryTypeIdentifierSleepAnalysis",
            unit: "min",
            tm_measurement_name: "sleep_pattern",
            tm_unit_name: "min",
            accessType: "readAndWrite"
          },
          source: null,
          date: startOfDaytime,
          start: startOfDaytime,
          end: endOfDayTime,
          value: totalSleep,
          sleep_pattern: totalSleep
        };

        let awakeSleepObj = { 
          dataType:{
            name: "sleepPattern",
            class: "HKCategoryTypeIdentifierSleepAnalysis",
            unit: "min",
            tm_measurement_name: "sleep_pattern_awake",
            tm_unit_name: "min",
            accessType: "readAndWrite"
          },
          source: null,
          date: startOfDaytime,
          start: startOfDaytime,
          end: endOfDayTime, 
          value: awakeTotal,
          sleep_pattern_awake: awakeTotal       
        };

        let restlessSleepObj = {
          dataType:{
            name: "sleepPattern",
            class: "HKCategoryTypeIdentifierSleepAnalysis",
            unit: "min",
            tm_measurement_name: "sleep_pattern_restless",
            tm_unit_name: "min",
            accessType: "readAndWrite"
          },
          source: null,
          date: startOfDaytime,
          start: startOfDaytime,
          end: endOfDayTime, 
          value: restlessTotal,
          sleep_pattern_restless: restlessTotal          
        };

        let asleepSleepObj = {
          dataType:{
            name: "sleepPattern",
            class: "HKCategoryTypeIdentifierSleepAnalysis",
            unit: "min",
            tm_measurement_name: "sleep_pattern_asleep",
            tm_unit_name: "min",
            accessType: "readAndWrite"
          },
          source: null,
          date: startOfDaytime,
          start: startOfDaytime,
          end: endOfDayTime, 
          value: asleepTotal,
          sleep_pattern_asleep: asleepTotal         
        };  

        sleepResObject.measurements.push(totalSleepObj);
        sleepResObject.measurements.push(asleepSleepObj);
        sleepResObject.measurements.push(awakeSleepObj);
        sleepResObject.measurements.push(restlessSleepObj);
        resultArray.push(sleepResObject);
      }

      passes--;
      startOfDaytime = moment(startOfDaytime).add(24, 'hours').toDate();
      endOfDayTime = moment(endOfDayTime).add(24, 'hours').toDate();
    } while (passes > 0);
    return resultArray;
  }

  getDateString(dateVal: Date):string {
    return dateVal.getFullYear()+"-"+dateVal.getMonth()+"-"+dateVal.getDate();
  }

  private getSleepType(val: HKCategoryValueSleepAnalysis): string {
    let res = "";
    if (val == HKCategoryValueSleepAnalysis.InBed) {
      res = "inbed";
    } else if (val == HKCategoryValueSleepAnalysis.Awake) {
      res = "awake";
    } else if (val == HKCategoryValueSleepAnalysis.Asleep) {
      res = "asleep";
    }
    return res;
  }

  requestAuthorization(): Promise<boolean> {
    return new Promise<boolean>((resolve, reject) => {
      if (this.healthStore === undefined) {
        reject("Health not available");
        return;
      }
      let readDataTypes = NSMutableSet.alloc<HKObjectType>().init();
      let writeDataTypes = NSMutableSet.alloc<HKObjectType>().init();
      let _writeDataTypes = NSMutableSet.alloc<HKSampleType>().init();
      this.types.filter(t => t.accessType === "write" || t.accessType === "readAndWrite")
      .forEach(t => writeDataTypes.addObject(HKSampleType.quantityTypeForIdentifier(t.class)));

      this.types.filter(t => t.accessType === "read" || t.accessType === "readAndWrite")
      .forEach(t => readDataTypes.addObject(HKObjectType.quantityTypeForIdentifier(t.class)));
      this.types.filter(t => t.accessType === "write" || t.accessType === "readAndWrite")
      .forEach(t => writeDataTypes.addObject(HKObjectType.quantityTypeForIdentifier(t.class)));

      this.healthStore.requestAuthorizationToShareTypesReadTypesCompletion( _writeDataTypes, readDataTypes, (success, error) => {
        if (success) {
          resolve(true);
        } else {
          reject('You do not have permissions for requested data type');
        }
      });
    });
  } 

  isAuthorized(): Promise<boolean> {
    return new Promise<boolean>((resolve, reject) => {
      if (this.healthStore === undefined) {
        reject("Health not available");
        return;
      }

      let authorized = true;
      this.types.forEach(t => {
        authorized = authorized &&
          this.healthStore.authorizationStatusForType(HKObjectType.quantityTypeForIdentifier(t.class)) === HKAuthorizationStatus.SharingAuthorized;
      });
      resolve(authorized);
    });
  }

  async query(options: QueryRequest): Promise<any> {
    console.log("HealthKit: Querying all Data");
    // let promises: Array<Promise<any>> = [];
    let results = [];
    for (var item of this.types) {
      let endDate = options.endDate || new Date();
      let startDate = options.startDate || new Date();

      let opts: QueryRequest = {
        startDate: startDate,
        endDate: endDate,
        dataType: item,
        aggregateBy: options.aggregateBy || item.aggregate || "hour", // optional, one of: "hour", "day", "sourceAndDay"
        sortOrder: options.sortOrder || "desc" // optional, default "asc"
      };

      let result;
      if (item.aggregate && item.aggregate == 'day') { 
        result = await this.queryForAggregateData(opts)
      } else {
        result = await this.queryForQuantityData(opts);
      }

      results.push(result);
    }
    let sleepResult = await this.queryForSleepData();
    if (sleepResult) {
      // for (let i = 0; i < sleepResult.length; i++) {
      //   results.push(sleepResult[i]);
      // }
      //results.push(sleepResult);
    }

    return Promise.resolve(MyMobileHealthKit.parseData(results, sleepResult));
  }

  private queryForQuantityData(opts: QueryRequest) {
    let promise = new Promise((resolve, reject) => {

      let quantityType = HKObjectType.quantityTypeForIdentifier(opts.dataType.class);
      let predicate = HKQuery.predicateForSamplesWithStartDateEndDateOptions(opts.startDate, opts.endDate, HKQueryOptions.StrictStartDate);
      let endDateSortDescriptor = NSSortDescriptor.alloc().initWithKeyAscending(HKSampleSortIdentifierEndDate, opts.sortOrder !== "desc");
      let sortBy = NSArray.arrayWithObject<NSSortDescriptor>(endDateSortDescriptor);

      // note that passing an invalid 'unitString' will crash the app (can't catch that error either)
      let unit = HKUnit.unitFromString(opts.dataType.unit);

      console.log("HK Query for " + opts.dataType.class + " in units "+unit);

      let query = HKSampleQuery.alloc().initWithSampleTypePredicateLimitSortDescriptorsResultsHandler(quantityType, predicate, null, sortBy, (query, listResults, error) => {
        if (listResults) {
          console.log("Received " + listResults.count + " HealthKit results");
          const parsedData: Array<HealthResponseItem> = [];

          for (let index = 0; index < listResults.count; index++) {
            let sample: HKSample = listResults.objectAtIndex(index);
            let { startDate, endDate, source } = sample;

            let resultItem = <HealthResponseItem>{
              dataType: opts.dataType,
              source: source.name,
              start: startDate,
              end: endDate,
              date: endDate
            };

            // TODO other types, see https://github.com/Telerik-Verified-Plugins/HealthKit/blob/c6b15ea8096bae3e61dc71a3cb0098da44f411fd/src/ios/HealthKit.m#L1333
            if (sample instanceof HKQuantitySample) {
              if ((<HKQuantitySample>sample).quantity.isCompatibleWithUnit(unit)) {
                resultItem.value = (<HKQuantitySample>sample).quantity.doubleValueForUnit(unit);
              } else {
                console.log("Incompatible unit passed: " + opts.dataType.unit + " (" + unit + ")");
              }
            }

            console.dir(resultItem);
            parsedData.push(resultItem);
          }
          console.log("Got data for "+opts.dataType.name);
          resolve(parsedData);
        } else {
          reject(error);
        }
      });
      this.healthStore.executeQuery(query);
    });

    return promise;
  }



  private queryForAggregateData(opts: QueryRequest) {
    let promise = new Promise((resolve, reject) => {

      // If we are aggregating by day, we want to start at the beginning of the day.
      opts.startDate = moment(opts.startDate).startOf('day').toDate();
      opts.endDate = moment(opts.endDate).endOf('day').toDate();

      let quantityType = HKObjectType.quantityTypeForIdentifier(opts.dataType.class);
      let predicate = HKQuery.predicateForSamplesWithStartDateEndDateOptions(opts.startDate, opts.endDate, HKQueryOptions.StrictStartDate);
      let statOpt = HKStatisticsOptions.CumulativeSum 
      let unit = HKUnit.unitFromString(opts.dataType.unit);

      let interval = NSDateComponents.alloc().init();
      interval.day = 1;

      console.log("HKStats Query for " + opts.dataType.class );

      let components = NSDateComponents.alloc().init();
      components.year = opts.startDate.getUTCFullYear();
      components.month = opts.startDate.getUTCMonth() - 1;
      components.day = opts.startDate.getUTCDay();
      components.hour = 0;
      components.minute = 0;
      let anchorDate = NSCalendar.currentCalendar.dateFromComponents(<any>components);

      let query = HKStatisticsCollectionQuery.alloc().initWithQuantityTypeQuantitySamplePredicateOptionsAnchorDateIntervalComponents( 
        quantityType,
        predicate,
        statOpt,
        anchorDate,
        interval
      )

      query.initialResultsHandler = (query, statResults, error) => {
        if (statResults) {
          let parsedData: Array<HealthResponseItem> = [];

          statResults.enumerateStatisticsFromDateToDateWithBlock(
            opts.startDate, opts.endDate, (result, stop) => {

              let sumQuantity = result.sumQuantity()
              if( sumQuantity ){

                let resultItem = <HealthResponseItem>{
                  dataType: opts.dataType,
                  source: null,
                  start: result.startDate,
                  end: result.endDate,
                  date: result.startDate
                };

                if( sumQuantity.isCompatibleWithUnit(unit) ) {
                  resultItem.value = sumQuantity.doubleValueForUnit(unit);

                  if( opts.dataType.tm_measurement_name === "daily_steps" ) {
                    // steps are usually integers, but HK can split a step count across days
                    resultItem.value = Math.trunc( resultItem.value )
                  }

                  //console.log(resultItem);
                  parsedData.push( resultItem )
                } else {
                  console.log("Incompatible unit passed: " + opts.dataType.unit + " (" + unit + ")");
                }


              }
            }
          );

          console.log("Got data for "+opts.dataType.name);
          resolve(parsedData);      

        } else {
          reject( "ERROR")
        }      
      }

      this.healthStore.executeQuery(query);

    });

    return promise;
  }



}

